import { z } from "zod";
import {
  createTRPCRouter,
  protectedProcedure,
  publicProcedure,
  withPermission,
  formDataInput,
  formDataProcedure,
} from "../..";
import { runEffect } from "../../utils/run-effect";
import { processAndUploadFile } from "../../utils/image-upload";
import { storageService } from "@tepian-k3/services/storage";
import { Effect } from "effect";
import certificateQueries from "@tepian-k3/queries/pelatihan/certificate.queries";
import {
  createCertificateTemplateSchema,
  updateCertificateTemplateSchema,
  verifyCertificateSchema,
  revokeCertificateSchema,
} from "@tepian-k3/schema/pelatihan/certificate.schema";

export const certificateRouter = createTRPCRouter({
  // === Template Operations (Admin) ===

  uploadTemplateFile: withPermission("pelatihan-certificates.create")
    .input(formDataInput)
    .use(
      formDataProcedure(
        z.object({
          file: z.custom<File>((val) => val instanceof File, {
            message: "File berkas wajib diunggah",
          }),
        }),
      ),
    )
    .mutation(async ({ ctx }) =>
      runEffect(
        Effect.gen(function* () {
          const uploadedFile = yield* processAndUploadFile(
            ctx.input.data.file,
            {
              folder: "pelatihan/certificate-templates",
              allowedMimeTypes: [
                "application/pdf",
                "image/png",
                "image/jpeg",
              ],
            },
          );
          return {
            key: uploadedFile.key,
            url: storageService.getPublicUrl(uploadedFile.key),
            name: ctx.input.data.file.name,
          };
        }),
      ),
    ),

  createTemplate: withPermission("pelatihan-certificates.create")
    .input(createCertificateTemplateSchema)
    .mutation(async ({ input, ctx }) => {
      return await runEffect(
        certificateQueries.createTemplate(input, ctx.user.id, ctx.user.email)
      );
    }),

  getTemplates: withPermission("pelatihan-certificates.read")
    .input(z.object({ pelatihanId: z.string().uuid() }))
    .query(async ({ input }) => {
      return await runEffect(certificateQueries.getTemplates(input.pelatihanId));
    }),

  getTemplateById: withPermission("pelatihan-certificates.read")
    .input(z.object({ id: z.string().uuid() }))
    .query(async ({ input }) => {
      return await runEffect(certificateQueries.getTemplateById(input.id));
    }),

  updateTemplate: withPermission("pelatihan-certificates.update")
    .input(updateCertificateTemplateSchema)
    .mutation(async ({ input, ctx }) => {
      return await runEffect(
        certificateQueries.updateTemplate(input, ctx.user.id, ctx.user.email)
      );
    }),

  setActiveTemplate: withPermission("pelatihan-certificates.update")
    .input(z.object({ pelatihanId: z.string().uuid(), templateId: z.string().uuid() }))
    .mutation(async ({ input, ctx }) => {
      return await runEffect(
        certificateQueries.setActiveTemplate(
          input.pelatihanId,
          input.templateId,
          ctx.user.id,
          ctx.user.email
        )
      );
    }),

  deleteTemplate: withPermission("pelatihan-certificates.delete")
    .input(z.object({ id: z.string().uuid() }))
    .mutation(async ({ input, ctx }) => {
      return await runEffect(
        certificateQueries.deleteTemplate(input.id, ctx.user.id, ctx.user.email)
      );
    }),

  // === Certificate Operations (User) ===

  checkEligibility: protectedProcedure
    .input(z.object({ enrollmentId: z.string().uuid() }))
    .query(async ({ input, ctx }) => {
      return await runEffect(
        certificateQueries.checkCompletionEligibility(ctx.user.id, input.enrollmentId)
      );
    }),

  requestCertificate: protectedProcedure
    .input(z.object({ enrollmentId: z.string().uuid() }))
    .mutation(async ({ input, ctx }) => {
      return await runEffect(
        certificateQueries.issueCertificate(ctx.user.id, input.enrollmentId, ctx.user.email)
      );
    }),

  getMyCertificate: protectedProcedure
    .input(z.object({ enrollmentId: z.string().uuid() }))
    .query(async ({ input, ctx }) => {
      return await runEffect(
        certificateQueries.getCertificateByEnrollment(input.enrollmentId, ctx.user.id)
      );
    }),

  // === Certificate Operations (Admin) ===

  getCertificatesByPelatihan: withPermission("pelatihan-certificates.read")
    .input(
      z.object({
        pelatihanId: z.string().uuid(),
        page: z.number().int().positive().default(1),
        limit: z.number().int().positive().max(100).default(10),
        search: z.string().optional(),
      })
    )
    .query(async ({ input }) => {
      const { pelatihanId, ...pagination } = input;
      return await runEffect(
        certificateQueries.getCertificatesByPelatihan(pelatihanId, pagination)
      );
    }),

  getAllCertificates: withPermission("pelatihan-certificates.read")
    .input(
      z.object({
        page: z.number().int().positive().default(1),
        limit: z.number().int().positive().max(100).default(10),
        search: z.string().optional(),
        pelatihanId: z.string().uuid().optional(),
        type: z.enum(["elearning", "bimtek", "webinar"]).optional(),
        status: z.enum(["active", "expired"]).optional(),
      })
    )
    .query(async ({ input }) => {
      return await runEffect(certificateQueries.getAllCertificates(input));
    }),

  issueCertificateManual: withPermission("pelatihan-certificates.create")
    .input(z.object({ enrollmentId: z.string().uuid() }))
    .mutation(async ({ input, ctx }) => {
      return await runEffect(
        certificateQueries.issueCertificateManual(
          input.enrollmentId,
          ctx.user.id,
          ctx.user.email
        )
      );
    }),

  revokeCertificate: withPermission("pelatihan-certificates.update")
    .input(revokeCertificateSchema)
    .mutation(async ({ input, ctx }) => {
      return await runEffect(
        certificateQueries.revokeCertificate(
          input.certificateId,
          input.reason,
          ctx.user.id,
          ctx.user.email
        )
      );
    }),

  // === Public Operations ===

  verifyCertificate: publicProcedure
    .input(verifyCertificateSchema)
    .query(async ({ input }) => {
      return await runEffect(certificateQueries.verifyCertificate(input.token));
    }),
});
